def _calzature_al_negozio(apps, schema_editor):
    """Le calzature si ordinano al negozio. Si cambia da Impostazioni, categoria per categoria."""
    CategoriaDPI = apps.get_model("dpi", "CategoriaDPI")
    for cat in CategoriaDPI.objects.all():
        nome = (cat.nome or "").casefold()
        if (cat.icona_emoji or "").strip() in _ICONE_CALZATURE or "scarp" in nome or "calzat" in nome:
            cat.si_ordina_al_negozio = True
            cat.save(update_fields=["si_ordina_al_negozio"])


